if info.get('seasons'):
    self.season_info = info.get('seasons')
    for seainfo in info.get('seasons'):
        # 季
        season = seainfo.get("season_number")
        if season is None:
            continue
        # 集
        episode_count = seainfo.get("episode_count")
        self.seasons[season] = list(range(1, episode_count + 1))

if self.type == MediaType.TV and not self.seasons:
    meta = MetaInfo(info.get("title"))
    season = meta.begin_season if meta.begin_season is not None else 1
    episodes_count = info.get("episodes_count")
    if episodes_count:
        self.seasons[season] = list(range(1, episodes_count + 1))

def get_tv_group_seasons(self, group_id: str) -> List[dict]:
    """
    获取电视剧剧集组季集列表
    """
    if not self.tv:
        return []
    try:
        logger.debug(f"正在获取剧集组：{group_id}...")
        group_seasons = self.tv.group_episodes(group_id) or []
        return [
            {
                **group_season,
                "episodes": [
                    {**ep, "episode_number": idx}
                    # 剧集组中每个季的episode_number从1开始
                    for idx, ep in enumerate(group_season.get("episodes", []), start=1)
                ]
            }
            for group_season in group_seasons
        ]
    except Exception as e:
        logger.error(str(e))
        return []

def _process_episode_groups(self, mediainfo: MediaInfo, episode_group: Optional[str],
                            group_seasons: List[dict]) -> MediaInfo:
    """
    处理剧集组信息
    """
    if mediainfo.type == MediaType.TV and mediainfo.episode_groups:
        if group_seasons:
            self._fill_group_season_info(mediainfo, episode_group, group_seasons)

for plugin, module_dict in self.pluginmanager.get_plugin_modules().items():
    plugin_id, plugin_name = plugin
    if method in module_dict:
        func = module_dict[method]
        if func:
            try:
                logger.info(f"请求插件 {plugin_name} 执行：{method} ...")
                if self.__is_valid_empty(result):
                    # 返回None，第一次执行或者需继续执行下一模块
                    result = func(*args, **kwargs)
                elif isinstance(result, list):
                    # 返回为列表，有多个模块运行结果时进行合并
                    temp = func(*args, **kwargs)
                    if isinstance(temp, list):
                        result.extend(temp)
                else:
                    break

with fresh(not cache):
    mediainfo = self.run_module(
        "recognize_media",
